//
// Sort, index BAM file and run samtools stats, flagstat and idxstats
//

include { SAMTOOLS_SORT      } from 'nf-core/samtools/sort'
include { SAMTOOLS_INDEX     } from 'nf-core/samtools/index'
include { BAM_STATS_SAMTOOLS } from 'nf-core/bam_stats_samtools'

workflow BAM_SORT_STATS_SAMTOOLS {
    take:
    ch_bam // channel: [ val(meta), [ bam ] ]
    ch_fasta_fai // channel: [ val(meta), path(fasta), path(fai) ]

    main:
    SAMTOOLS_SORT(ch_bam, ch_fasta_fai, '')

    SAMTOOLS_INDEX(SAMTOOLS_SORT.out.bam)

    SAMTOOLS_SORT.out.bam
        .join(SAMTOOLS_INDEX.out.index, by: [0])
        .set { ch_bam_bai }

    BAM_STATS_SAMTOOLS(ch_bam_bai, ch_fasta_fai)

    emit:
    bam      = SAMTOOLS_SORT.out.bam // channel: [ val(meta), [ bam ] ]
    index    = SAMTOOLS_INDEX.out.index // channel: [ val(meta), [ index ] ]
    stats    = BAM_STATS_SAMTOOLS.out.stats // channel: [ val(meta), [ stats ] ]
    flagstat = BAM_STATS_SAMTOOLS.out.flagstat // channel: [ val(meta), [ flagstat ] ]
    idxstats = BAM_STATS_SAMTOOLS.out.idxstats // channel: [ val(meta), [ idxstats ] ]
}

nextflow_workflow {

    name "Test Workflow BAM_SORT_STATS_SAMTOOLS"
    script "../main.nf"
    workflow "BAM_SORT_STATS_SAMTOOLS"
    tag "subworkflows"
    tag "subworkflows_nfcore"
    tag "subworkflows/bam_sort_stats_samtools"
    tag "bam_sort_stats_samtools"
    tag "subworkflows/bam_stats_samtools"
    tag "subworkflows/../bam_stats_samtools"
    tag "bam_stats_samtools"
    tag "samtools"
    tag "samtools/index"
    tag "samtools/sort"
    tag "samtools/stats"
    tag "samtools/idxstats"
    tag "samtools/flagstat"

    test("test_bam_sort_stats_samtools_single_end") {

        when {
            workflow {
                """
                input[0] = Channel.of([
                    [ id:'test', single_end:false ], // meta map
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bam/test.single_end.bam', checkIfExists: true)
                ])
                input[1] = Channel.of([
                    [ id:'genome' ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta.fai', checkIfExists: true)
                ])
                """
            }
        }

        then {
            assertAll(
                { assert workflow.success},
                { assert workflow.out.bam.get(0).get(1) ==~ ".*.bam"},
                { assert workflow.out.index.get(0).get(1) ==~ ".*.bai"},
                { assert snapshot(
                    workflow.out.flagstat,
                    workflow.out.idxstats,
                    workflow.out.stats).match() }
            )
        }
    }

    test("test_bam_sort_stats_samtools_paired_end") {

        when {
            workflow {
                """
                input[0] = Channel.of([
                    [ id:'test', single_end:false ], // meta map
